// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));

        c.initialize();
        address initialOwner = c.owner();

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        bool prop;
        if (caller == initialOwner) {
            prop = ok && (c.owner() == newOwner);
        } else {
            prop = (!ok) && (c.owner() == initialOwner);
        }

        assertTrue(prop);
    }
}
